const std = @import("std"); const rigz = @import("te-brow-rig.zig"); const acts = @import("nt-brow-acts.zig"); const cfgz = @import("cf-conf-load.zig");
fn con2(rig3: *rigz.Rigg, path: []const u8, nee2: []const u8) !usize { const recz = (try rig3.reco(path)) orelse return 0; return std.mem.count(u8, recz.body, nee2); }
test "infinite scroll: all 50 rows collected, equals the declared total" { var rig3: rigz.Rigg = undefined; try rig3.upzz(.{}); defer rig3.down(); try rig3.skipNozz(); rig3.ladz.acts = .{ .scrl = 30 }; const out2 = try rig3.gozz("/scroll"); try std.testing.expectEqualStrings("brow", out2.vend); try std.testing.expectEqual(@as(usize, 50), try con2(&rig3, "/scroll", "Row number ")); try std.testing.expectEqual(@as(usize, 1), try con2(&rig3, "/scroll", "Total rows: 50")); }
test "scroll cap stops a runaway page" { var conf: cfgz.Conf = .{}; conf.brow_scrl_maxz = 1; var rig3: rigz.Rigg = undefined; try rig3.upzz(conf); defer rig3.down(); try rig3.skipNozz(); rig3.ladz.acts = .{ .scrl = 30 }; _ = try rig3.gozz("/scroll"); const rows = try con2(&rig3, "/scroll", "Row number "); try std.testing.expect(rows < 50 and rows >= 10); }
test "load more button clicked until gone: 30 items" { var rig3: rigz.Rigg = undefined; try rig3.upzz(.{}); defer rig3.down(); try rig3.skipNozz(); rig3.ladz.acts = .{ .clic = "load more" }; _ = try rig3.gozz("/more"); try std.testing.expectEqual(@as(usize, 30), try con2(&rig3, "/more", "Item number ")); }
test "consent wall dismissed through cons_sele_list; without the flag the text stays hidden" { var rig3: rigz.Rigg = undefined; try rig3.upzz(.{}); defer rig3.down(); try rig3.skipNozz(); rig3.ladz.acts = .{ .cons = true }; _ = try rig3.gozz("/consent"); try std.testing.expectEqual(@as(usize, 1), try con2(&rig3, "/consent", "Secret article body revealed after consent")); var rig2: rigz.Rigg = undefined; try rig2.upzz(.{}); defer rig2.down(); try rig2.skipNozz(); rig2.ladz.acts = .{ .scrl = 1 }; _ = try rig2.gozz("/consent"); try std.testing.expectEqual(@as(usize, 0), try con2(&rig2, "/consent", "Secret article body")); }
test "3-step search form from a steps file: type, click, wait, extract" { var rig3: rigz.Rigg = undefined; try rig3.upzz(.{}); defer rig3.down(); try rig3.skipNozz(); const stpz = try acts.stepRead(rig3.aren.allocator(), "[{\"op\":\"type\",\"sele\":\"#q\",\"text\":\"widgets\"},{\"op\":\"click\",\"sele\":\"#go\"},{\"op\":\"waitsel\",\"sele\":\"#results\"},{\"op\":\"extract\",\"sele\":\"#results\"}]", 50); rig3.ladz.acts = .{ .ste2 = stpz }; _ = try rig3.gozz("/form"); try std.testing.expectEqual(@as(usize, 2), try con2(&rig3, "/form", "Results for widgets: 5 items")); }
test "typing into a password field is refused, never typed" { var rig3: rigz.Rigg = undefined; try rig3.upzz(.{}); defer rig3.down(); try rig3.skipNozz(); const stpz = try acts.stepRead(rig3.aren.allocator(), "[{\"op\":\"type\",\"sele\":\"#pw\",\"text\":\"hunter2\"}]", 50); rig3.ladz.acts = .{ .ste2 = stpz }; try std.testing.expectError(error.BrowFail, rig3.gozz("/form")); try std.testing.expect((try rig3.reco("/form")) == null); }
test "step file: too many steps and unknown ops are typed errors" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); try std.testing.expectError(error.StepLimit, acts.stepRead(aren.allocator(), "[{\"op\":\"wait\"},{\"op\":\"wait\"},{\"op\":\"wait\"}]", 2)); try std.testing.expectError(error.BadSteps, acts.stepRead(aren.allocator(), "[{\"op\":\"rm -rf\"}]", 50)); try std.testing.expectError(error.BadSteps, acts.stepRead(aren.allocator(), "not json", 50)); }
test "actions without a browser are a typed error, never a silent vendor call" { var conf: cfgz.Conf = .{}; conf.brow_path_exec = "/no/such/chrome"; var rig3: rigz.Rigg = undefined; try rig3.upzz(conf); defer rig3.down(); rig3.ladz.acts = .{ .scrl = 3 }; try std.testing.expectError(error.NoBrowser, rig3.gozz("/scroll")); try std.testing.expectEqual(@as(usize, 0), rig3.vmkz.cal3.items.len); }
test "step time cap: a long wait is cut by brow_time_seco" { var conf: cfgz.Conf = .{}; conf.brow_time_seco = 2; var rig3: rigz.Rigg = undefined; try rig3.upzz(conf); defer rig3.down(); try rig3.skipNozz(); const stpz = try acts.stepRead(rig3.aren.allocator(), "[{\"op\":\"wait\",\"ms\":30000},{\"op\":\"wait\",\"ms\":30000},{\"op\":\"waitsel\",\"sele\":\"#never\"}]", 50); rig3.ladz.acts = .{ .ste2 = stpz }; try std.testing.expectError(error.BrowFail, rig3.gozz("/form")); }
